import com.notireader.app.databinding.BottomSheetPermissionBinding

class StoragePermissionBottomSheet : BottomSheetDialogFragment() {
    private var _binding: BottomSheetPermissionBinding? = null
    private val binding get() = _binding!!

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?
    ): View? {
        _binding = BottomSheetPermissionBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        binding.permissionTitle.text = "Storage Permission"
        binding.permissionDescription.text = "This app needs access to your WhatsApp media folder to save and display media."
        binding.allowButton.setOnClickListener {
            (activity as? MainActivity)?.checkAndRequestFolderPermission()
            dismiss()
        }
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.notireader.app.presentation.view_chat_screen_activity
import android.os.Bundle import androidx.activity.enableEdgeToEdge import androidx.activity.viewModels import androidx.appcompat.app.AppCompatActivity import androidx.core.view.ViewCompat import androidx.core.view.WindowInsetsCompat import androidx.lifecycle.Observer import androidx.recyclerview.widget.LinearLayoutManager import com.notireader.app.databinding.ActivityViewChatBinding import dagger.hilt.android.AndroidEntryPoint
@AndroidEntryPoint class ViewChatActivity : AppCompatActivity() { private val viewModel: ViewChatViewModel by viewModels() private lateinit var binding: ActivityViewChatBinding override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState) enableEdgeToEdge() binding = ActivityViewChatBinding.inflate(layoutInflater) setContentView(binding.root) ViewCompat.setOnApplyWindowInsetsListener(binding.main) { v, insets -> val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars()) v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom) insets } val senderName = intent.getStringExtra("sender_name") ?: "" binding.senderTitle.text = senderName binding.messageRecyclerView.layoutManager = LinearLayoutManager(this) viewModel.getMessagesForSender(senderName).observe(this, Observer { messages -> binding.messageRecyclerView.adapter = ViewChatAdapter(messages) }) } }

package com.notireader.app.presentation.view_chat_screen_activity
import android.os.Bundle import androidx.activity.enableEdgeToEdge import androidx.activity.viewModels import androidx.appcompat.app.AppCompatActivity import androidx.core.view.ViewCompat import androidx.core.view.WindowInsetsCompat import androidx.lifecycle.Observer import androidx.recyclerview.widget.LinearLayoutManager import com.notireader.app.databinding.ActivityViewChatBinding import dagger.hilt.android.AndroidEntryPoint
@AndroidEntryPoint class ViewChatActivity : AppCompatActivity() { private val viewModel: ViewChatViewModel by viewModels() private lateinit var binding: ActivityViewChatBinding override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState) enableEdgeToEdge() binding = ActivityViewChatBinding.inflate(layoutInflater) setContentView(binding.root) ViewCompat.setOnApplyWindowInsetsListener(binding.main) { v, insets -> val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars()) v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom) insets } val senderName = intent.getStringExtra("sender_name") ?: "" binding.senderTitle.text = senderName binding.messageRecyclerView.layoutManager = LinearLayoutManager(this) viewModel.getMessagesForSender(senderName).observe(this, Observer { messages -> binding.messageRecyclerView.adapter = ViewChatAdapter(messages) }) binding.backButton.setOnClickListener { finish() } } }

package com.notireader.app.presentation.whatsapp_screen_fragment

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.recyclerview.widget.RecyclerView
import com.notireader.app.databinding.ItemSenderBinding

class SenderAdapter(
    private val senders: List<String>,
    private val onClick: (String) -> Unit
) : RecyclerView.Adapter<SenderAdapter.SenderViewHolder>() {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): SenderViewHolder {
        val binding = ItemSenderBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return SenderViewHolder(binding)
    }

    override fun onBindViewHolder(holder: SenderViewHolder, position: Int) {
        holder.bind(senders[position])
    }

    override fun getItemCount(): Int = senders.size

    inner class SenderViewHolder(private val binding: ItemSenderBinding) : RecyclerView.ViewHolder(binding.root) {
        fun bind(sender: String) {
            binding.senderName.text = sender
            binding.root.setOnClickListener { onClick(sender) }
        }
    }
}
